{"outputKey":"configurazioneEsito","code":"function t(v) { return v == null ? '' : ('' + v).trim(); }
function segnaposto(v) { return /^<[^>]*>$/.test(v); }
function leggiJson(v) {
  var g = t(v);
  if (g === '') return { ok: true, val: null };
  try { return { ok: true, val: JSON.parse(g) }; } catch (_) {}
  try { return { ok: true, val: JSON.parse(g.replace(/\\u([0-9a-fA-F]{4})/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); })) }; } catch (e2) {}
  return { ok: false, val: null };
}
var errori = [];
var obbligatori = ['ragioneSocialeAzienda', 'pivaAzienda', 'workRoot', 'operatorEmail', 'agentCode', 'agentVersion', 'cartelleJson'];
for (var i = 0; i < obbligatori.length; i++) {
  var v = t(stepData[obbligatori[i]]);
  if (v === '' || segnaposto(v)) errori.push(obbligatori[i] + ' non compilato');
}
var piva = t(stepData.pivaAzienda).replace(/\D/g, '');
if (!segnaposto(t(stepData.pivaAzienda)) && t(stepData.pivaAzienda) !== '' && piva.length < 8) errori.push('pivaAzienda non valida: ' + t(stepData.pivaAzienda));
if (piva !== '') stepData.pivaAzienda = piva;
var reMail = /^[^\s@;,]+@[^\s@;,]+\.[A-Za-z]{2,}$/;
if (t(stepData.operatorEmail) !== '' && !reMail.test(t(stepData.operatorEmail))) errori.push('operatorEmail non valida (un solo indirizzo): ' + t(stepData.operatorEmail));
if (t(stepData.operatorEmailCc) === '') stepData.operatorEmailCc = t(stepData.operatorEmail);
else if (!reMail.test(t(stepData.operatorEmailCc))) errori.push('operatorEmailCc non valida (un solo indirizzo): ' + t(stepData.operatorEmailCc));
if (t(stepData.prefissoOggettoMail) === '') stepData.prefissoOggettoMail = '[Ordini Clienti]';
var dep = leggiJson(stepData.depositiJson);
var causaleDef = t(stepData.causaleDefault), depositoDef = t(stepData.depositoDefault);
if (!dep.ok || (dep.val !== null && !Array.isArray(dep.val))) errori.push('depositiJson non e un elenco JSON valido');
else {
  var voci = dep.val || [];
  for (var k = 0; k < voci.length; k++) {
    var vo = voci[k] || {};
    if (t(vo.deposito) === '' || t(vo.causale) === '') errori.push('depositiJson voce ' + (k + 1) + ': deposito e causale obbligatori');
    if (vo.campiTestata != null && (typeof vo.campiTestata !== 'object' || Array.isArray(vo.campiTestata))) errori.push('depositiJson voce ' + (k + 1) + ': campiTestata deve essere un oggetto');
  }
  if (voci.length === 0 && (causaleDef === '' || depositoDef === '')) errori.push('depositiJson vuoto: compilarlo oppure impostare causaleDefault e depositoDefault');
}
if (depositoDef !== '' && causaleDef === '') errori.push('depositoDefault impostato senza causaleDefault');
var ct = leggiJson(stepData.campiTestataJson);
if (!ct.ok || (ct.val !== null && (typeof ct.val !== 'object' || Array.isArray(ct.val)))) errori.push('campiTestataJson deve essere un oggetto JSON, es. {"CAMPO":"valore"}');
else stepData.campiTestataJson = JSON.stringify(ct.val || {});
var pr = leggiJson(stepData.programmazioniJson);
if (!pr.ok || (pr.val !== null && !Array.isArray(pr.val))) errori.push('programmazioniJson non e un elenco JSON valido');
if (errori.length) throw new Error('Configurazione azienda incompleta: ' + errori.join('; ') + '. Correggere lo step CONFIGURAZIONE AZIENDA.');
return { azienda: t(stepData.ragioneSocialeAzienda), piva: stepData.pivaAzienda, depositi: (dep.val || []).length, causaleDefault: causaleDef, email: t(stepData.operatorEmail) };"}

{"outputKey":"preflightEsito","code":"// Meglio non partire affatto che scoprire a meta' lavorazione di non poter scrivere il log:
// sul DDT fornitori questo controllo ci ha risparmiato una passata cieca.
var righe = [];
try { righe = JSON.parse(String(stepData.lastQueryJson || '[]')); } catch (_) { righe = []; }
if (!Array.isArray(righe)) righe = [];
var r = righe.length ? righe[0] : {};
function n(nome) { return Number(r[nome] || r[nome.toLowerCase()] || 0); }
var mancanze = [];
if (n('WF_LOG') === 0 || n('WF_LOG_RIGHE') === 0) mancanze.push('tabelle THINKAI_WF_* assenti');
if (n('AGENTE_REGISTRATO') === 0) mancanze.push('agente non registrato in THINKAI_WF_AGENTI');
if (n('PUO_INSERIRE') === 0 || n('PUO_AGGIORNARE') === 0 || n('PUO_INSERIRE_RIGHE') === 0) mancanze.push('permessi di scrittura mancanti');
stepData.wfSchemaReady = mancanze.length === 0 ? 'true' : 'false';
stepData.wfSchemaMotivo = mancanze.join('; ');
return { pronto: stepData.wfSchemaReady, motivo: stepData.wfSchemaMotivo };"}

{"outputKey":"verificaGestionale","code":"// V1.29 - Target Cross raggiungibile? Si prova UNA volta a inizio run: se il servizio TcRestAPI e'
// fermo non si tocca nessun file e a fine run parte una mail per l'assistenza (max una all'ora).
var ok = stepData.lastTargetCrossSucceeded === true || String(stepData.lastTargetCrossSucceeded) === 'true';
stepData.gestionaleGiu = ok ? 'false' : 'true';
stepData.gestionaleErrore = ok ? '' : String(stepData.lastTargetCrossError || stepData.lastGestionaleEsito || 'nessuna risposta');
var n = new Date();
function p2(x) { return (x < 10 ? '0' : '') + x; }
stepData.oraAvvisoGestionale = n.getUTCFullYear() + '-' + p2(n.getUTCMonth() + 1) + '-' + p2(n.getUTCDate()) + 'T' + p2(n.getUTCHours());
return { raggiungibile: ok, errore: stepData.gestionaleErrore };"}

{"outputKey":"cartelleEsito","code":"// Un FileList ricorsivo sulla radice ripescherebbe anche processing/, review/ ed error/,
// rimettendo in lavorazione i file gia' scartati. Si cicla invece sulle cartelle dichiarate,
// una alla volta, non ricorsive.
var root = String(stepData.workRoot || '').replace(/[\\\/]+$/, '');
// La configurazione delle cartelle arriva come JSON dentro un campo di testo, quindi passa per
// un editor e per due serializzazioni. Finora un errore li' dentro finiva nel catch e lasciava
// l'elenco vuoto: l'agente girava senza lavorare NIENTE e senza dire niente, che il giorno
// dell'installazione e' il modo peggiore di sbagliare. Ora o si legge o si ferma.
var grezzo = String(stepData.cartelleJson || '').trim();
var elenco = null;
if (grezzo !== '') {
  try { elenco = JSON.parse(grezzo); }
  catch (_) {
    // Tolleranza: se il valore e' passato per un editor che ha lasciato gli escape \uXXXX
    // letterali, le virgolette sono arrivate come sei caratteri invece che come uno.
    try {
      elenco = JSON.parse(grezzo.replace(/\\u([0-9a-fA-F]{4})/g, function (m, h) { return String.fromCharCode(parseInt(h, 16)); }));
    } catch (e2) { elenco = null; }
  }
}
if (grezzo === '') {
  throw new Error('cartelleJson non configurato: senza almeno una cartella d ingresso l agente non ha niente da leggere.');
}
if (elenco === null || !Array.isArray(elenco)) {
  throw new Error('cartelleJson non leggibile come JSON. Atteso un elenco tipo [{"nome":"OrdineDiretto","chiusura":false},{"nome":"OrdineConChiusura","chiusura":true}]. Valore ricevuto (primi 120 caratteri): ' + grezzo.substring(0, 120));
}
// Dalla V1.4 la cartella non dice piu' reparto, causale e deposito: quelli si ricavano
// dall'anagrafica articolo. La cartella dice una cosa sola, ma pesante: cosa fare quando
// l'ordine esiste gia' (decisione azienda 16/09).
stepData.cartelle = elenco.map(function (c) {
  return {
    nome: String(c.nome || '').trim(),
    chiusura: (c.chiusura === true || String(c.chiusura) === 'true'),
    percorso: root + '\\' + String(c.nome || '').trim()
  };
}).filter(function (c) { return c.nome !== ''; });
if (stepData.cartelle.length === 0) {
  throw new Error('cartelleJson letto ma nessuna cartella utilizzabile: ogni voce deve avere un "nome" non vuoto. Voci trovate: ' + elenco.length + '.');
}
return { cartelle: stepData.cartelle.length, nomi: stepData.cartelle.map(function (c) { return c.nome; }).join(', ') };"}
